python - <<'PY'
from rcb_client import Robot
import numpy as np
r=Robot(); o=r.get_obs(include_depth=True,video='none')
for cam in ('head_camera','front_camera'):
 im=o.last[cam]; dep=o.depth[cam][0].astype(float)
 print('\n',cam, im.shape)
 for label,m in [('blue',(im[:,:,2]>150)&(im[:,:,0]<100)&(im[:,:,1]<120)),('dark',(im[:,:,0]<75)&(im[:,:,1]<78)&(im[:,:,2]<85))]:
  ys,xs=np.where(m)
  print(label,'n',len(xs),'bbox', (xs.min(),ys.min(),xs.max(),ys.max()) if len(xs) else None)
  if label=='blue':
   for y,x in zip(ys[::max(1,len(ys)//10)],xs[::max(1,len(xs)//10)]): print(' ',x,y,im[y,x].tolist(),dep[y,x])
  else:
   # central dark cluster
   c=(xs>20)&(xs<290)&(ys<210)
   print(' central bbox', (xs[c].min(),ys[c].min(),xs[c].max(),ys[c].max()) if c.any() else None)
   if c.any():
    for y,x in zip(ys[c][::max(1,c.sum()//12)],xs[c][::max(1,c.sum()//12)]): print(' ',x,y,im[y,x].tolist(),dep[y,x])
